const titleEl = element.querySelector('#guide-section-title');
if (!titleEl) return;
const text = titleEl.textContent || '';
if (text.trim() !== 'More from YouTube') return;
const sectionsContainer = element.parentElement;
if (!sectionsContainer) return;
const firstChild = sectionsContainer.firstChild;
if (!firstChild) return;
if (sectionsContainer.contains(element) && firstChild !== element) {
  sectionsContainer.insertBefore(element, firstChild);
}
